const expandArray = (baseArr, targetCount, mutator) => {
  const res = [...baseArr];
  let i = 0;
  while (res.length < targetCount) {
    res.push(mutator(baseArr[i % baseArr.length], res.length));
    i++;
  }
  return res;
};

