const ScreenMatchDetail = ({ matchId, onBack, onApply }) => {
  const [rationale, setRationale] = useState([]);
  const [loading, setLoading] = useState(true);

  const match = SEED_MATCHES.find(m => m.id === matchId) || SEED_MATCHES[1];
  const role = SEED_ROLES.find(r => r.id === match.role_id);

  useEffect(() => {
    const getRationale = async () => {
      try {
        const res = await callAIWithVS(
          "You are an encouraging, transparent career coach. Explain a numeric fit score in 3 plain-language bullets. Highlight the strongest overlapping competencies, identify the specific gaps, and explain what it would take to close them. Never guarantee placement. Output strictly valid JSON.",
          `Generate rationale for a ${match.fit_score}% match between student stu-001 and role ${role.title}.`
        );
        const parsed = JSON.parse(res.text);
        setRationale(parsed.rationale_bullets || match.rationale_bullets);
      } catch (e) {
        setRationale(match.rationale_bullets);
      } finally {
        setLoading(false);
      }
    };
    getRationale();
  }, [matchId]);

  const renderRadar = () => {
    const size = 240;
    const center = size / 2;
    const radius = 80;
    const axes = role.required_competencies.slice(0, 5);
    const angleStep = (Math.PI * 2) / axes.length;

    const getPoint = (val, i) => {
      const r = (val / 4) * radius;
      const a = i * angleStep - Math.PI / 2;
      return `${center + r * Math.cos(a)},${center + r * Math.sin(a)}`;
    };

    const reqPoints = axes.map((a, i) => getPoint(a.min_proficiency, i)).join(' ');

    const actualPoints = axes.map((a, i) => {
      const isMissing = match.missing_competencies.includes(a.skill);
      const isPartial = match.partial_competencies.includes(a.skill);
      let val = a.min_proficiency;
      if (isMissing) val = 0;
      if (isPartial) val = Math.max(1, a.min_proficiency - 1);
      if (!isMissing && !isPartial) val = Math.min(4, a.min_proficiency + 1);
      return getPoint(val, i);
    }).join(' ');

    return (
      <svg width={size} height={size} className="p-chart">
        {[1,2,3,4].map(level => (
          <polygon key={level} points={axes.map((_, i) => getPoint(level, i)).join(' ')} fill="none" stroke="var(--brand-hairline)" />
        ))}
        {axes.map((_, i) => (
          <line key={i} x1={center} y1={center} x2={center + radius * Math.cos(i * angleStep - Math.PI/2)} y2={center + radius * Math.sin(i * angleStep - Math.PI/2)} stroke="var(--brand-hairline)" />
        ))}
        <polygon points={reqPoints} fill="none" stroke="var(--brand-grey)" strokeWidth="2" strokeDasharray="4 4" />
        <motion.polygon 
          points={actualPoints} 
          fill="var(--brand-source)" fillOpacity="0.2" 
          stroke="var(--brand-source)" strokeWidth="2"
          initial={{ opacity: 0, scale: 0.8 }}
          animate={{ opacity: 1, scale: 1 }}
          style={{ transformOrigin: 'center' }}
        />
        {axes.map((a, i) => {
          const x = center + (radius + 20) * Math.cos(i * angleStep - Math.PI/2);
          const y = center + (radius + 20) * Math.sin(i * angleStep - Math.PI/2);
          return <text key={i} x={x} y={y} fontSize="10" fill="var(--brand-grey)" textAnchor="middle" dominantBaseline="middle">{a.skill.split(' ')[0]}</text>
        })}
      </svg>
    );
  };

  return (
    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="app-container">
      <header style={{ marginBottom: 32 }}>
        <button aria-label="Back to feed" onClick={onBack} style={{ color: 'var(--brand-grey)', marginBottom: 16, display: 'flex', alignItems: 'center', gap: 4, fontWeight: 700 }}>
          <lucide.ArrowLeft size={16} /> Back to Feed
        </button>
        <h1>{role.title}</h1>
        <h2 style={{ fontSize: 20, color: 'var(--brand-grey)', fontWeight: 400 }}>{role.employer} • {role.location}</h2>
      </header>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 32 }}>
        <section>
          <div className="nu-card p-chart-container" style={{ marginBottom: 24 }}>
            {renderRadar()}
          </div>

          <div className="nu-card p-6 p-diff">
            <h3 style={{ marginBottom: 16 }}>Competency Gap Analysis</h3>
            {match.missing_competencies.map(c => (
              <div key={c} style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 8, paddingBottom: 8, borderBottom: '1px solid var(--brand-hairline)' }}>
                <span style={{ fontWeight: 700 }}>{c}</span>
                <span className="del">Required: {profLabel(role.required_competencies.find(r=>r.skill===c)?.min_proficiency)} | Actual: None</span>
              </div>
            ))}
            {match.partial_competencies.map(c => (
              <div key={c} style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 8, paddingBottom: 8, borderBottom: '1px solid var(--brand-hairline)' }}>
                <span style={{ fontWeight: 700 }}>{c}</span>
                <span className="amber" style={{ color: 'var(--brand-gold)' }}>Required: {profLabel(role.required_competencies.find(r=>r.skill===c)?.min_proficiency)} | Actual: Lower</span>
              </div>
            ))}
            {match.missing_competencies.length === 0 && match.partial_competencies.length === 0 && (
              <p style={{ color: 'var(--brand-source)' }}>All required competencies met or exceeded.</p>
            )}
          </div>
        </section>

        <section>
          <div className="nu-card p-6 p-synth" style={{ marginBottom: 24 }}>
            <h3 style={{ marginBottom: 16 }}>Why you're a {match.fit_score}% fit</h3>
            {loading ? (
              <div className="skeleton" style={{ height: 100 }} />
            ) : (
              <ul style={{ paddingLeft: 20, color: 'var(--brand-ink)' }}>
                {rationale.map((r, i) => <li key={i} style={{ marginBottom: 12 }}>{r}</li>)}
              </ul>
            )}
          </div>

          <div className="nu-card p-6" style={{ background: 'var(--brand-rail)', color: 'var(--brand-paper)' }}>
            <h3 style={{ color: 'var(--brand-paper)', marginBottom: 8 }}>Ready to apply?</h3>
            <p style={{ color: 'var(--brand-grey)', marginBottom: 24, fontSize: 14 }}>We'll tailor your resume bullets to emphasize the required competencies for this specific role.</p>
            <button aria-label="Tailor and apply" className="nu-btn-primary" style={{ width: '100%' }} onClick={() => onApply(matchId)}>
              Tailor & Apply
            </button>
          </div>
        </section>
      </div>
    </motion.div>
  );
};

