      try {
        const res = await callAIWithVS(
          "You are an expert resume writer. Rewrite the student's base resume bullets to emphasize the competencies required by the target role. Draft a tailored cover letter anchored to the role's requirements and the student's verified strengths. Output as tracked changes. Output strictly valid JSON.",
          "Tailor resume and draft cover letter for role Clinical Data Co-op."
        );
        const parsed = JSON.parse(res.text);
        setChanges(parsed.resume_changes || [
          { id: 1, orig: "Conducted lab experiments and recorded data.", sugg: "Conducted clinical lab experiments, utilizing statistical methods to analyze and record data." },
          { id: 2, orig: "Wrote reports on findings.", sugg: "Authored scientific reports detailing data analysis outcomes for clinical stakeholders." }
        ]);
      } catch (e) {
        setChanges([
          { id: 1, orig: "Conducted lab experiments and recorded data.", sugg: "Conducted clinical lab experiments, utilizing statistical methods to analyze and record data." },
          { id: 2, orig: "Wrote reports on findings.", sugg: "Authored scientific reports detailing data analysis outcomes for clinical stakeholders." }
        ]);
      } finally {
        setLoading(false);
      }
    };
    getTailoring();
  }, []);

  const handleAccept = (id) => {
    setAccepted(prev => ({ ...prev, [id]: true }));
    setRelevance(prev => Math.min(98, prev + 10));
  };

  return (
    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="app-container">
      <header style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', marginBottom: 32 }}>
        <div>
          <h1>Tailor Application</h1>
          <h2 style={{ fontSize: 20, color: 'var(--brand-grey)', fontWeight: 400 }}>Clinical Data Co-op • Moderna</h2>
        </div>
        <div style={{ textAlign: 'right' }}>
          <div style={{ fontSize: 12, textTransform: 'uppercase', fontWeight: 700, color: 'var(--brand-grey)' }}>Relevance Score</div>
          <div style={{ fontSize: 32, fontWeight: 700, color: 'var(--brand-source)' }} className="tabular-data">{relevance}%</div>
        </div>
      </header>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 24, marginBottom: 32 }}>
        <div className="nu-card p-6">
          <h3 style={{ marginBottom: 16, color: 'var(--brand-grey)' }}>Original Resume</h3>
          {loading ? (
            <div className="skeleton" style={{ height: 100 }} />
          ) : (
            <ul style={{ paddingLeft: 20, color: 'var(--brand-grey)', fontSize: 14 }}>
              {changes.map(c => <li key={`orig-${c.id}`} style={{ marginBottom: 16 }}>{c.orig}</li>)}
            </ul>
          )}
        </div>

        <div className="nu-card p-6 p-diff">
          <h3 style={{ marginBottom: 16 }}>Tailored Suggestions</h3>
          {loading ? (
            <div className="skeleton" style={{ height: 100 }} />
          ) : changes.map(c => (
            <div key={`sugg-${c.id}`} style={{ marginBottom: 24, padding: 16, background: accepted[c.id] ? 'transparent' : 'var(--brand-canvas)', border: accepted[c.id] ? 'none' : '1px solid var(--brand-hairline)', borderRadius: 4 }}>
              {accepted[c.id] ? (
                <p style={{ fontSize: 14 }}>• {c.sugg}</p>
              ) : (
                <>
                  <p className="add" style={{ marginBottom: 12 }}>• {c.sugg}</p>
                  <div className="flex gap-2">
                    <button aria-label="Accept suggestion" className="nu-btn-secondary" style={{ padding: '6px 12px', fontSize: 12 }} onClick={() => handleAccept(c.id)}>Accept</button>
                    <button aria-label="Reject suggestion" style={{ color: 'var(--brand-grey)', fontSize: 12, fontWeight: 700, padding: '6px 12px' }}>Reject</button>
                  </div>
                </>
              )}
            </div>
          ))}
        </div>
      </div>

      <footer className="nu-card p-6 flex justify-between items-center" style={{ background: 'var(--brand-rail)', color: 'var(--brand-paper)' }}>
        <p>Review all changes before submitting to Moderna.</p>
        <button aria-label="Submit application" className="nu-btn-primary" onClick={onComplete}>Submit Application</button>
      </footer>
    </motion.div>
  );
};

