// --- MAIN APP ---
const App = () => {
  const [currentScreen, setCurrentScreen] = useState('screen_onboarding_intake');
  const [selectedRoleId, setSelectedRoleId] = useState(null);

  useEffect(() => {
    const style = document.createElement('style');
    style.innerHTML = NU_THEME;
    document.head.appendChild(style);
    return () => document.head.removeChild(style);
  }, []);

  const renderScreen = () => {
    switch (currentScreen) {
      case 'screen_onboarding_intake':
        return <ScreenOnboardingIntake onComplete={() => setCurrentScreen('screen_match_feed')} />;
      case 'screen_match_feed':
        return <ScreenMatchFeed 
          onSelectRole={(id) => { setSelectedRoleId(id); setCurrentScreen('screen_match_detail'); }} 
          onUnlockClick={() => setCurrentScreen('screen_skill_gap_plan')}
        />;
      case 'screen_match_detail':
        return <ScreenMatchDetail 
          matchId={selectedRoleId} 
          onBack={() => setCurrentScreen('screen_match_feed')}
          onApply={() => setCurrentScreen('screen_resume_tailor')}
        />;
      case 'screen_skill_gap_plan':
        return <ScreenSkillGapPlan onBack={() => setCurrentScreen('screen_match_feed')} />;
      case 'screen_resume_tailor':
        return <ScreenResumeTailor onComplete={() => setCurrentScreen('screen_match_feed')} />;
      case 'screen_cohort_readiness':
        return <ScreenCohortReadiness />;
      default:
        return <div>Screen not found</div>;
    }
  };

  return (
    <div data-brand="nu" style={{ minHeight: '100vh', display: 'flex', flexDirection: 'column' }}>
      {currentScreen !== 'screen_onboarding_intake' && <Header onNav={setCurrentScreen} />}

      <main style={{ flex: 1 }}>
        <AnimatePresence mode="wait">
          <Fragment key={currentScreen}>
            {renderScreen()}
          </Fragment>
        </AnimatePresence>
      </main>

      <div style={{ position: 'fixed', bottom: 16, right: 16, zIndex: 9999, background: 'var(--brand-rail)', padding: 12, borderRadius: 8, boxShadow: 'var(--shadow-hover)', display: 'flex', gap: 8, alignItems: 'center' }}>
        <span style={{ color: 'var(--brand-grey)', fontSize: 10, textTransform: 'uppercase', fontWeight: 700 }}>Demo Jump</span>
        <select 
          aria-label="Demo screen jump"
          value={currentScreen} 
          onChange={(e) => setCurrentScreen(e.target.value)}
          style={{ background: 'var(--brand-ink)', color: 'var(--brand-paper)', border: '1px solid var(--brand-grey)', padding: '4px 8px', borderRadius: 4, fontSize: 12 }}
        >
          <option value="screen_onboarding_intake">1. Intake</option>
          <option value="screen_match_feed">2. Feed</option>
          <option value="screen_match_detail">3. Detail</option>
          <option value="screen_skill_gap_plan">4. Gap Plan</option>
          <option value="screen_resume_tailor">5. Tailor</option>
          <option value="screen_cohort_readiness">6. Cohort</option>
        </select>
      </div>
    </div>
  );
};

function __test_state_transitions__() {
  console.assert(typeof App === 'function', 'App must be a component');
  return true;
}
if (typeof window !== 'undefined') {
  window.__hicProtoTests = __test_state_transitions__;
}
